topic_name = #{topicName}, topic_category = #{topicCategory}, keywords = #{keywords}, exclude_words = #{excludeWords}, platform_scope = #{platformScope}, source_scope = #{sourceScope}, risk_level = #{riskLevel}, responsible_department_id = #{responsibleDepartmentId}, enabled = #{enabled}, description = #{description}, update_user_id = #{updateUserId}
